{
  "items": [
    {
      "name": "Nat.lt_pow_of_log_lt",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b x y : ℕ}, 1 < b → Nat.log b y < x → y < b ^ x"
    },
    {
      "name": "pow_lt_pow_left₀",
      "module_name": "Mathlib.Algebra.Order.GroupWithZero.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {M₀ : Type u_2} [inst : MonoidWithZero M₀] [inst_1 : PartialOrder M₀] {a b : M₀} [PosMulStrictMono M₀]\n  [MulPosMono M₀], a < b → 0 ≤ a → ∀ {n : ℕ}, n ≠ 0 → a ^ n < b ^ n"
    },
    {
      "name": "zpow_lt_zpow_right₀",
      "module_name": "Mathlib.Algebra.Order.GroupWithZero.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {G₀ : Type u_3} [inst : GroupWithZero G₀] [inst_1 : PartialOrder G₀] [PosMulReflectLT G₀] {a : G₀} [ZeroLEOneClass G₀]\n  {m n : ℤ}, 1 < a → m < n → a ^ m < a ^ n"
    },
    {
      "name": "pow_le_pow_iff_right₀",
      "module_name": "Mathlib.Algebra.Order.GroupWithZero.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {M₀ : Type u_2} [inst : MonoidWithZero M₀] [inst_1 : PartialOrder M₀] {a : M₀} {m n : ℕ} [PosMulStrictMono M₀]\n  [ZeroLEOneClass M₀], 1 < a → (a ^ n ≤ a ^ m ↔ n ≤ m)"
    },
    {
      "name": "zpow_le_zpow_left₀",
      "module_name": "Mathlib.Algebra.Order.GroupWithZero.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {G₀ : Type u_3} [inst : GroupWithZero G₀] [inst_1 : PartialOrder G₀] [PosMulReflectLT G₀] {a b : G₀} [MulPosMono G₀]\n  {n : ℤ}, 0 ≤ n → 0 ≤ a → a ≤ b → a ^ n ≤ b ^ n"
    }
  ]
}
